rules:
default allow := false

allow if {
  input.source_auth.method
  input.source_auth.method != "failed"
}

default allow := false

jwt_claim_values(v) := [v] if is_string(v)

jwt_claim_values(v) := v if is_array(v)

allow if {
  input.source_auth.method == "jwt_bearer"
  some v in jwt_claim_values(input.source_auth.claims[{{claim}}])
  v in {{values}}
}

default allow := false

jwt_audiences contains a if {
  a := input.source_auth.claims.aud
  is_string(a)
}

jwt_audiences contains a if {
  is_array(input.source_auth.claims.aud)
  some a in input.source_auth.claims.aud
}

allow if {
  input.source_auth.method == "jwt_bearer"
  input.source_auth.claims.iss in {{issuers}}
  some a in jwt_audiences
  a in {{audiences}}
}

default allow := false

allow if {
  input.source_auth.claims.role in {{admin_roles}}
  input.mcp.method == "tools/call"
}

allow if {
  input.source_auth.subject
  input.mcp.method == "tools/call"
  input.mcp.tool_name in {{safe_tools}}
}

allow if {
  input.source_auth.subject
  input.mcp.method != "tools/call"
}

default allow := false

allow if {
  input.agent.did
  input.agent.trust_verification == true
}

default allow := false

allow if {
  input.extension_identity.verified == true
  input.extension_identity.did in {{dids}}
}

default allow := false

allow if input.gateway.direction != "outbound"

allow if {
  input.gateway.direction == "outbound"
  some prefix in {{destinations}}
  startswith(input.gateway.target_id, prefix)
}

default allow := false

allow if {
  now := time.now_ns()
  time.weekday([now, {{time_zone}}]) in {{days}}
  [hour, _, _] := time.clock([now, {{time_zone}}])
  hour >= {{start_hour}}
  hour < {{end_hour}}
}

default allow := false

allow if {
  count(input.trust_check_results.target) > 0
  every r in input.trust_check_results.target { r.ok }
}

default allow := false

allow if {
  passing := [r | some r in input.trust_check_results.target; r.ok]
  count(passing) >= {{min_passing}}
}

default allow := false

path_prefix_unsafe if contains(input.http.path, "..")

path_prefix_unsafe if contains(lower(input.http.path), "%2e")

path_prefix_unsafe if contains(input.http.path, "\\")

path_prefix_unsafe if contains(lower(input.http.path), "%5c")

allow if {
  not path_prefix_unsafe
  some prefix in {{prefixes}}
  startswith(input.http.path, prefix)
}

default allow := false

allow if {
  input.source_auth.method == "jwt_bearer"
  input.source_auth.subject in {{subjects}}
}

default allow := false

tool_claim_values(v) := [v] if is_string(v)

tool_claim_values(v) := v if is_array(v)

allow if {
  some v in tool_claim_values(input.jwt[{{claim}}])
  v in {{values}}
}

default allow := false

allow if input.jwt.role == {{admin_role}}

deny_reason := "The caller's token has no role" if not input.jwt.role

deny_reason := sprintf("Role %v may not call this tool", [input.jwt.role]) if {
  input.jwt.role
  input.jwt.role != {{admin_role}}
}
